import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { PencilIcon, TrashIcon, PlusIcon, HomeIcon } from "@heroicons/react/24/outline";
import { motion } from "framer-motion";
import "animate.css";
import "../styles/main.css";
import { API } from "../utils";
import ToothIcon from "../assets/tooth-icon.png"; // pastikan kamu punya ikon gigi di folder ini

const ObatList = () => {
  const navigate = useNavigate();
  const [obat, setObat] = useState([]);
  const [msg, setMsg] = useState("");

  useEffect(() => {
    const fetchObat = async () => {
      try {
        const token = localStorage.getItem("accessToken");
        if (!token) {
          setMsg("Silakan login terlebih dahulu.");
          return;
        }
        const response = await API.get("/obat", {
          headers: { Authorization: `Bearer ${token}` },
          withCredentials: true,
        });
        setObat(response.data);
      } catch (error) {
        console.error("Gagal mengambil data obat:", error);
      }
    };
    fetchObat();
  }, []);

  const navigateToDashboard = () => navigate("/dashboard");
  const handleTambah = () => navigate("/add-obat");
  const handleEdit = (obat) => navigate(`/obat/edit/${obat.id_obat}`);
  const handleDelete = async (item) => {
    try {
      const token = localStorage.getItem("accessToken");
      await API.delete(`/obat/${item.id_obat}`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      setObat(obat.filter(o => o.id_obat !== item.id_obat));
    } catch (error) {
      console.error("Gagal menghapus obat:", error);
    }
  };

  return (
    <motion.div
      className="container mt-6 animate__animated animate__fadeIn"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      transition={{ duration: 0.8 }}
    >
      <div className="level mb-4">
        <div className="level-left title-wrapper">
          <img src={ToothIcon} alt="tooth-icon" className="icon-gigi" />
          <h1 className="title is-3">Daftar Obat Klinik Gigi</h1>
        </div>
        <div className="level-right">
          <button onClick={navigateToDashboard} className="button is-light mr-2" title="Kembali ke Dashboard">
            <HomeIcon className="h-5 w-5" />
          </button>
          <motion.button
            onClick={handleTambah}
            className="button is-primary"
            whileHover={{ scale: 1.05 }}
            whileTap={{ scale: 0.95 }}
          >
            <PlusIcon className="h-5 w-5 mr-1" /> Tambah Obat
          </motion.button>
        </div>
      </div>

      {msg && <p className="has-text-danger">{msg}</p>}

      <div className="table-container">
        <motion.table
          className="table is-bordered is-striped is-hoverable is-fullwidth animate__animated animate__zoomIn"
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5 }}
        >
          <thead>
            <tr>
              <th>#</th>
              <th>Nama Obat</th>
              <th>Definisi</th>
              <th>Efek Samping</th>
              <th>Harga</th>
              <th className="has-text-centered">Aksi</th>
            </tr>
          </thead>
          <tbody>
            {obat.length ? (
              obat.map((item, idx) => (
                <motion.tr
                  key={item.id_obat}
                  whileHover={{ scale: 1.02 }}
                  transition={{ type: "spring", stiffness: 300 }}
                >
                  <td>{idx + 1}</td>
                  <td>{item.nama_obat}</td>
                  <td>{item.definisi}</td>
                  <td>{item.efek_samping}</td>
                  <td>{item.harga}</td>
                  <td className="has-text-centered">
                    <motion.button
                      className="button is-small is-info mr-1"
                      whileTap={{ scale: 0.9 }}
                      onClick={() => handleEdit(item)}
                    >
                      <PencilIcon className="h-4 w-4" />
                    </motion.button>
                    <motion.button
                      className="button is-small is-danger"
                      whileTap={{ scale: 0.9 }}
                      onClick={() => handleDelete(item)}
                    >
                      <TrashIcon className="h-4 w-4" />
                    </motion.button>
                  </td>
                </motion.tr>
              ))
            ) : (
              <tr>
                <td colSpan={6} className="has-text-centered has-text-grey">
                  Tidak ada data obat.
                </td>
              </tr>
            )}
          </tbody>
        </motion.table>
      </div>
    </motion.div>
  );
};

export default ObatList;
